<?php
namespace App\Services\Operation;
use App\Core\BaseService; use App\Exceptions\ConflictApiException; use App\Exceptions\NotFoundApiException; use App\Exceptions\TenantAccessDeniedException; use App\Libraries\ListQuery; use App\Models\VisitorEntryModel; use Config\Database;
class VisitorEntryService extends BaseService
{
    public function __construct(private readonly VisitorEntryModel $model = new VisitorEntryModel(), private readonly VisitorInviteService $inviteService = new VisitorInviteService(), private readonly VehicleAccessListService $accessService = new VehicleAccessListService()){ parent::__construct(); }
    public function list(array $query): array { $q=ListQuery::normalize($query,['sortable'=>['id','entered_at','exited_at','direction','created_at'],'filterable'=>['site_id','unit_id','entry_type','direction']]); $b=$this->model->builder()->select('*')->where('deleted_at',null); foreach($q['filters'] as $f=>$v){$b->where($f,$v);} if($q['search']!==''){$b->groupStart()->like('visitor_name',$q['search'])->orLike('vehicle_plate',$q['search'])->groupEnd();} $t=(int)$b->countAllResults(false); $i=$b->orderBy($q['sort'],$q['direction'])->limit($q['per_page'],($q['page']-1)*$q['per_page'])->get()->getResultArray(); return ListQuery::envelope($q['page'],$q['per_page'],$t,$i);}
    public function show(int $id): array { $this->assertAccessible($id); $r=$this->model->tenantFind($id); if(!is_array($r)){throw new NotFoundApiException('Visitor entry bulunamadi');} return $r; }
    public function checkIn(array $payload): array { $entryType=(string)$payload['entry_type']; if($entryType==='invite'){ if(empty($payload['visitor_invite_id'])){throw new ConflictApiException('invite check-in icin visitor_invite_id zorunlu');} $db=Database::connect(); $db->transBegin(); try{ $invite=$this->inviteService->lockForCheckIn((int)$payload['visitor_invite_id']); $plate=$this->inviteService->normalizePlate($invite['vehicle_plate']??null); if((string)$invite['status']!=='active'){throw new ConflictApiException('Invite active degil');} $now=time(); if($now<strtotime((string)$invite['valid_from']) || $now>strtotime((string)$invite['valid_until'])){throw new ConflictApiException('Invite tarih araligi disinda');} if((int)$invite['used_count']>=(int)$invite['max_uses']){throw new ConflictApiException('Invite kullanim limiti dolmus');} if($this->accessService->isBlacklisted((int)$invite['site_id'],$plate)){throw new ConflictApiException('Blacklist plate check-in engellendi');} $newUsed=(int)$invite['used_count']+1; $newStatus=$newUsed>=(int)$invite['max_uses']?'used':'active'; $this->inviteService->updateUsageAfterLock((int)$invite['id'],$newUsed,$newStatus); $this->model->insert(['site_id'=>(int)$invite['site_id'],'unit_id'=>(int)$invite['unit_id'],'visitor_invite_id'=>(int)$invite['id'],'visitor_name'=>(string)$invite['visitor_name'],'visitor_phone'=>$invite['visitor_phone']??null,'vehicle_plate'=>$plate,'entry_type'=>'invite','direction'=>'in','entered_at'=>date('Y-m-d H:i:s'),'recorded_by'=>$payload['recorded_by']??null,'notes'=>$payload['notes']??null],true); if($db->transStatus()===false){throw new ConflictApiException('Check-in islemi tamamlanamadi');} $db->transCommit(); $id=(int)$this->model->getInsertID(); $entry=$this->show($id); $this->audit('security.visitor_entry.check_in.success',['entity_type'=>'visitor_entry','entity_id'=>$id,'new_values'=>$entry,'meta'=>['invite_status'=>$newStatus]]); return $entry; } catch(\Throwable $e){$db->transRollback(); throw $e;} } if(empty($payload['site_id'])||empty($payload['visitor_name'])){throw new ConflictApiException('manual check-in icin site_id ve visitor_name zorunlu');} $siteId=(int)$payload['site_id']; $this->assertSiteUnit($siteId,isset($payload['unit_id'])?(int)$payload['unit_id']:null); $plate=$this->inviteService->normalizePlate($payload['vehicle_plate']??null); if($this->accessService->isBlacklisted($siteId,$plate)){throw new ConflictApiException('Blacklist plate manual check-in engellendi');} $this->model->insert(['site_id'=>$siteId,'unit_id'=>$payload['unit_id']??null,'visitor_invite_id'=>null,'visitor_name'=>(string)$payload['visitor_name'],'visitor_phone'=>$payload['visitor_phone']??null,'vehicle_plate'=>$plate,'entry_type'=>'manual','direction'=>'in','entered_at'=>date('Y-m-d H:i:s'),'recorded_by'=>$payload['recorded_by']??null,'notes'=>$payload['notes']??null],true); $id=(int)$this->model->getInsertID(); $entry=$this->show($id); $this->audit('security.visitor_entry.check_in.success',['entity_type'=>'visitor_entry','entity_id'=>$id,'new_values'=>$entry]); return $entry; }
    public function checkOut(array $payload): array { $entryId=(int)$payload['entry_id']; $old=$this->show($entryId); if((string)$old['direction']!=='in' || ($old['exited_at']??null)!==null){throw new ConflictApiException('Acik entry check-out icin uygun degil');} $this->model->update($entryId,['direction'=>'out','exited_at'=>date('Y-m-d H:i:s'),'recorded_by'=>$payload['recorded_by']??$old['recorded_by'],'notes'=>$payload['notes']??$old['notes']]); $n=$this->show($entryId); $this->audit('security.visitor_entry.check_out.success',['entity_type'=>'visitor_entry','entity_id'=>$entryId,'old_values'=>$old,'new_values'=>$n]); return $n; }
    private function assertSiteUnit(int $siteId,?int $unitId): void { $db=Database::connect(); $ctx=(int)(service('request')->company_id??0); $s=$db->table('sites')->where('id',$siteId)->where('deleted_at',null)->get(1)->getRowArray(); if(!is_array($s)){throw new NotFoundApiException('Site bulunamadi');} if($ctx>0&&(int)$s['company_id']!==$ctx){throw new TenantAccessDeniedException('Cross-tenant erisim engellendi');} if($unitId!==null){$u=$db->table('units')->where('id',$unitId)->where('deleted_at',null)->get(1)->getRowArray(); if(!is_array($u)){throw new NotFoundApiException('Unit bulunamadi');} if((int)$u['site_id']!==$siteId){throw new ConflictApiException('unit/site uyumsuz');} if($ctx>0&&(int)$u['company_id']!==$ctx){throw new TenantAccessDeniedException('Cross-tenant erisim engellendi');}} }
    private function assertAccessible(int $id): void { $r=Database::connect()->table('visitor_entries')->where('id',$id)->get(1)->getRowArray(); if(!is_array($r)||($r['deleted_at']??null)!==null){throw new NotFoundApiException('Visitor entry bulunamadi');} $ctx=(int)(service('request')->company_id??0); if($ctx>0&&(int)$r['company_id']!==$ctx){throw new TenantAccessDeniedException('Cross-tenant erisim engellendi');} }
}
